#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n = 6;
    vector<int> sequence;
    sequence.push_back(n);
    while (n != 1) {
        if (n % 2 == 0) {
            n = n / 2;
        } else {
            n = 3 * n + 1;
        }
        sequence.push_back(n);
    }
    return 0;
}
